"""
    Get intensity after subtracting the background.
    :param bg: a float of calculated background
    :param intensity_ave: 1D list of averaged intensity
    :return: 1D list of intensity with background subtracted
    """
def calculate_intensity_avg_no_bg(bg: Any, intensity_ave: Any) -> object {
    intensity_ave_no_bg = [(i - bg) for i in intensity_ave];
    for index in range(len(intensity_ave_no_bg)) {
        intensity_ave_no_bg[index] = 0
            if (intensity_ave_no_bg[index] < 0)
            else intensity_ave_no_bg[index];
    }
    return intensity_ave_no_bg;
}

"""
    USed to convert a list of dictionaries to a dictionary using some common properties (i.e. name)
    Careful as data will be lost for duplicate entries, this assumes the list is a "set".
    :param list_to_convert: A list of dictionaries
    :param key_name: A value from each dict to use as the key.
    :return: A dictionary.
    """
def list_to_dict(list_to_convert: dict, key_name: str) -> object {
    converted_dict = `dict();
    if list_to_convert {
        for item in list_to_convert {
            converted_dict[item[key_name]] = item;
        }
    }
    return converted_dict;
}

"""Save a Vocab file for test."""
def save_a_vocab_file(vocab_file: Any, vocab_list: Any) -> object {
    with open(vocab_file, "w", encoding='utf-8') as out_f {
        for vocab in vocab_list {
            out_f.write(vocab);
            out_f.write('\n');
        }
    }
    return vocab_file;
}

