"""
    Return weight given an entity grammatical role.
    +-----------+--------+
    | EGrid Tag | Weight |
    +===========+========+
    | S         | 3      |
    +-----------+--------+
    | O         | 2      |
    +-----------+--------+
    | X         | 1      |
    +-----------+--------+
    | dash      | 0      |
    +-----------+--------+
    """
def weighting_syntactic_role(entity_role: Any) -> object {
    if (entity_role == "S") {
        return 3;
    } elif (entity_role == "O") {
        return 2;
    } elif (entity_role == "X") {
        return 1;
    }
    return 0;
}

